head.b:skin:
/*
-----------------------------------------------
Blogger Tema Bilgileri
Name:     Manowa Manga, Manhwa & Novel Teması
Version:  1.1.0
-----------------------------------------------

<Variable name="keycolor" description="Ana Renk Teması" type="color" default="#f97316" value="#f97316"/>
<Variable name="body.background" description="Arka Plan Resmi" color="$(body.background.color)" type="background" default="$(color) none repeat scroll top left" value="$(color) none repeat scroll top left"/>

<Group description="1. Koyu Tema Arka Plan Renkleri" selector="body">
  <Variable name="body.background.color" description="Birincil Arka Plan (--bg-primary)" type="color" default="#0f1117" value="#0f1117"/>
  <Variable name="theme.bg.secondary" description="İkincil Panel Arka Planı (--bg-secondary)" type="color" default="#181b24" value="#181b24"/>
  <Variable name="theme.bg.card" description="Kart ve Kutu Arka Planı (--bg-card)" type="color" default="#1f2330" value="#1f2330"/>
  <Variable name="theme.border.color" description="Kenarlık Rengi (--border-color)" type="color" default="#2e3446" value="#2e3446"/>
</Group>

<Group description="2. Metin ve Vurgu Renkleri" selector=".site-main">
  <Variable name="theme.text.primary" description="Birincil Metin Rengi (--text-primary)" type="color" default="#f1f5f9" value="#f1f5f9"/>
  <Variable name="theme.text.secondary" description="İkincil Açıklama Metni (--text-secondary)" type="color" default="#94a3b8" value="#94a3b8"/>
  <Variable name="theme.accent.primary" description="Ana Vurgu Rengi (--accent-primary)" type="color" default="#f97316" value="#f97316"/>
  <Variable name="theme.accent.hover" description="Vurgu Üzerine Gelme Rengi (--accent-hover)" type="color" default="#fb923c" value="#fb923c"/>
</Group>

<Group description="3. Açık (Light) Tema Renkleri" selector="[data-theme='light']">
  <Variable name="light.bg.primary" description="Açık Tema Birincil Arka Plan" type="color" default="#f8fafc" value="#f8fafc"/>
  <Variable name="light.bg.secondary" description="Açık Tema İkincil Arka Plan" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="light.bg.card" description="Açık Tema Kart Arka Planı" type="color" default="#f1f5f9" value="#f1f5f9"/>
  <Variable name="light.text.primary" description="Açık Tema Birincil Metin" type="color" default="#0f172a" value="#0f172a"/>
  <Variable name="light.text.secondary" description="Açık Tema İkincil Metin" type="color" default="#475569" value="#475569"/>
  <Variable name="light.accent.primary" description="Açık Tema Vurgu Rengi" type="color" default="#ea580c" value="#ea580c"/>
  <Variable name="light.accent.hover" description="Açık Tema Vurgu Hover" type="color" default="#c2410c" value="#c2410c"/>
  <Variable name="light.border.color" description="Açık Tema Kenarlık Rengi" type="color" default="#e2e8f0" value="#e2e8f0"/>
</Group>

<Group description="4. Tür Rozeti Renkleri (Manhwa, Manga, Manhua, Novel)" selector=".catalog-grid">
  <Variable name="badge.kr.color" description="Manhwa (KR) Rozet Rengi" type="color" default="#ef4444" value="#ef4444"/>
  <Variable name="badge.jp.color" description="Manga (JP) Rozet Rengi" type="color" default="#ec4899" value="#ec4899"/>
  <Variable name="badge.cn.color" description="Manhua (CN) Rozet Rengi" type="color" default="#f59e0b" value="#f59e0b"/>
  <Variable name="badge.en.color" description="Novel / Diğer Rozet Rengi" type="color" default="#3b82f6" value="#3b82f6"/>
</Group>

<Group description="5. Tipografi ve Yazı Tipi" selector="body">
  <Variable name="body.font" description="Site Ana Yazı Tipi" type="font" default="normal normal 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" value="normal normal 16px 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"/>
</Group>

<Variable name="disqus.shortname" description="Disqus Forum Shortname" type="string" default="" value=""/>
<Variable name="theme.default.mode" description="Varsayılan Tema Modu (dark veya light)" type="string" default="dark" value="dark"/>
*/
/* {{STYLES}} */

/* === BLOGGER THEME DESIGNER VARIABLE BINDINGS === */
:root {
  --bg-primary: $(body.background.color);
  --bg-secondary: $(theme.bg.secondary);
  --bg-card: $(theme.bg.card);
  --text-primary: $(theme.text.primary);
  --text-secondary: $(theme.text.secondary);
  --accent-primary: $(theme.accent.primary);
  --accent-hover: $(theme.accent.hover);
  --badge-kr: $(badge.kr.color);
  --badge-jp: $(badge.jp.color);
  --badge-cn: $(badge.cn.color);
  --badge-en: $(badge.en.color);
  --border-color: $(theme.border.color);
}

[data-theme="light"] {
  --bg-primary: $(light.bg.primary);
  --bg-secondary: $(light.bg.secondary);
  --bg-card: $(light.bg.card);
  --text-primary: $(light.text.primary);
  --text-secondary: $(light.text.secondary);
  --accent-primary: $(light.accent.primary);
  --accent-hover: $(light.accent.hover);
  --border-color: $(light.border.color);
}

body {
  background: $(body.background);
  background-color: var(--bg-primary);
  font: $(body.font);
}

head.b:template-skin:
body#layout {
  background-color: #f8fafc;
  color: #0f172a;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  padding: 16px;
  margin: 0;
}
body#layout #top-app-bar,
body#layout #view-catalog,
body#layout #view-series,
body#layout #view-reader,
body#layout #view-bookmarks,
body#layout #view-history,
body#layout #view-generator,
body#layout #disqus-section,
body#layout #btn-scroll-top,
body#layout .site-footer > p {
  display: none !important;
}
body#layout .site-header,
body#layout .site-main,
body#layout .site-footer {
  max-width: 100%;
  padding: 0;
  margin: 0 0 12px 0;
  background: transparent;
  border: none;
}
body#layout .header-inner {
  max-width: 100%;
  padding: 0;
  display: block;
}
body#layout div.section {
  background: #ffffff;
  border: 1px dashed #f97316;
  border-radius: 10px;
  padding: 14px;
  margin: 0 0 14px 0;
  box-sizing: border-box;
}
body#layout #theme-config-section {
  display: block !important;
  background: #fff7ed;
  border: 2px solid #f97316;
}
body#layout #theme-config-section .widget {
  width: 48.5%;
  display: inline-block;
  vertical-align: top;
  margin: 4px 0.5%;
  box-sizing: border-box;
}
body#layout .blogger-layout-columns {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  width: 100%;
}
body#layout #main-blog-section {
  display: block !important;
  flex: 2;
  width: 65%;
  margin: 0;
}
body#layout #sidebar-gadgets-section {
  display: block !important;
  flex: 1;
  width: 35%;
  margin: 0;
}
